{"file_path":"src/parse.js","content":"/**
 * Parses an election description into a list of candidates (in declaration
 * order) and a list of ballots, each holding a BigInt count and an ordered
 * array of candidate names. Throws a ParseError carrying the offending line
 * number (or none, for the "no candidates" case) on any malformed input.
 */

const NAME_RE = /^[A-Za-z0-9_-]+$/
const COUNT_RE = /^[1-9][0-9]*$/

export class ParseError extends Error {
  constructor(message, line) {
    super(line === undefined ? `error: ${message}` : `error: line ${line}: ${message}`)
    this.line = line
  }
}

export function parseElection(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  let candidates = null // ordered array of names
  const candidateSet = new Set()
  const ballots = []

  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const trimmed = lines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue
    const tokens = trimmed.split(/\s+/)
    const directive = tokens[0]

    if (directive === 'candidates') {
      if (candidates !== null) {
        throw new ParseError('candidates must be declared once, before any ballot', lineNo)
      }
      const names = tokens.slice(1)
      if (names.length === 0) {
        throw new ParseError('expected candidates <name>...', lineNo)
      }
      candidates = []
      for (const name of names) {
        if (!NAME_RE.test(name)) {
          throw new ParseError(`invalid candidate name ${name}`, lineNo)
        }
        if (candidateSet.has(name)) {
          throw new ParseError(`candidate ${name} is declared twice`, lineNo)
        }
        candidateSet.add(name)
        candidates.push(name)
      }
    } else if (directive === 'ballot') {
      if (candidates === null) {
        throw new ParseError('candidates must be declared once, before any ballot', lineNo)
      }
      if (tokens.length < 3) {
        throw new ParseError('expected ballot <count> <candidate>...', lineNo)
      }
      const countToken = tokens[1]
      if (!COUNT_RE.test(countToken)) {
        throw new ParseError('count must be a positive integer', lineNo)
      }
      const count = BigInt(countToken)
      const names = tokens.slice(2)
      const seen = new Set()
      for (const name of names) {
        if (!candidateSet.has(name)) {
          throw new ParseError(`unknown candidate ${name}`, lineNo)
        }
        if (seen.has(name)) {
          throw new ParseError(`candidate ${name} is repeated`, lineNo)
        }
        seen.add(name)
      }
      ballots.push({ count, names })
    } else {
      throw new ParseError(`unknown directive ${directive}`, lineNo)
    }
  }

  if (candidates === null || candidates.length === 0) {
    throw new ParseError('no candidates')
  }

  return { candidates, ballots }
}
"}

