{"file_path":"src/count.js","content":"/**
 * Runs the instant-runoff count for an election, producing one entry per
 * round counted plus the eventual winner (or none).
 */

function tieBreakEliminate(tied, history) {
  let cands = tied.slice()
  for (const roundVotes of history) {
    if (cands.length === 1) break
    const vals = cands.map((c) => roundVotes.get(c))
    let min = vals[0]
    for (const v of vals) if (v < min) min = v
    const filtered = cands.filter((c, i) => vals[i] === min)
    if (filtered.length < cands.length) {
      cands = filtered
    }
  }
  if (cands.length === 1) return cands[0]
  let last = cands[0]
  for (const c of cands) if (c > last) last = c
  return last
}

export function countElection(candidates, ballots) {
  let continuing = new Set(candidates)
  const history = [] // array of Map(candidate -> BigInt votes), per round
  const rounds = [] // { votes: Map, exhausted: BigInt, eliminated: string|null }
  let winner = null

  for (;;) {
    const votes = new Map()
    for (const c of continuing) votes.set(c, 0n)
    let exhausted = 0n

    for (const ballot of ballots) {
      let target = null
      for (const name of ballot.names) {
        if (continuing.has(name)) {
          target = name
          break
        }
      }
      if (target === null) {
        exhausted += ballot.count
      } else {
        votes.set(target, votes.get(target) + ballot.count)
      }
    }

    history.push(votes)

    let activeTotal = 0n
    for (const v of votes.values()) activeTotal += v

    let eliminated = null

    if (activeTotal === 0n) {
      winner = null
      rounds.push({ votes, exhausted, eliminated })
      break
    }

    let majorityWinner = null
    for (const [name, v] of votes) {
      if (v * 2n > activeTotal) {
        majorityWinner = name
        break
      }
    }

    if (majorityWinner !== null) {
      winner = majorityWinner
      rounds.push({ votes, exhausted, eliminated })
      break
    }

    // Eliminate the candidate(s) with fewest votes this round.
    let min = null
    for (const v of votes.values()) {
      if (min === null || v < min) min = v
    }
    const tied = []
    for (const [name, v] of votes) {
      if (v === min) tied.push(name)
    }
    eliminated = tied.length === 1 ? tied[0] : tieBreakEliminate(tied, history)

    rounds.push({ votes, exhausted, eliminated })
    continuing = new Set([...continuing].filter((c) => c !== eliminated))
  }

  return { rounds, winner }
}
"}

