{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js rounds` prints every round of the instant-runoff
 * count read from standard input, and `node src/cli.js tally` prints only how
 * many rounds ran and who won.
 */

import { parseElection, ParseError } from './parse.js'
import { countElection } from './count.js'

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function readStdin() {
  const fs = require === undefined ? null : null
  return null
}

async function main() {
  const args = process.argv.slice(2)
  const mode = args[0]
  if (args.length !== 1 || (mode !== 'rounds' && mode !== 'tally')) {
    process.stderr.write('error: usage: cli.js rounds|tally\n')
    process.exit(2)
    return
  }

  const chunks = []
  for await (const chunk of process.stdin) chunks.push(chunk)
  const input = chunks.join('')

  let election
  try {
    election = parseElection(input)
  } catch (err) {
    if (err instanceof ParseError) {
      process.stderr.write(`${err.message}\n`)
      process.exit(2)
      return
    }
    throw err
  }

  const { rounds, winner } = countElection(election.candidates, election.ballots)

  const out = []
  if (mode === 'rounds') {
    rounds.forEach((round, idx) => {
      const entries = [...round.votes.entries()]
      entries.sort((a, b) => {
        if (a[1] !== b[1]) return a[1] > b[1] ? -1 : 1
        return a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0
      })
      const parts = entries.map(([name, v]) => `${name}=${v}`)
      out.push(`round ${idx + 1}: ${parts.join(' ')} exhausted=${round.exhausted}`)
      if (round.eliminated !== null) {
        out.push(`eliminated ${round.eliminated}`)
      }
    })
  } else {
    out.push(`rounds ${rounds.length}`)
  }

  out.push(winner === null ? 'no winner' : `winner ${winner}`)

  process.stdout.write(out.join('\n') + '\n')
}

main()
"}

